dict.string:
#!/bin/zsh
# Parse input: action|||app_name|||bundle_id|||app_path|||pids IFS='|||' read -r action app_name bundle_id app_path pids <<< "$1"
case "$action" in "open") if [[ -n "$app_path" && -d "$app_path" ]]; then open -a "$app_path" echo "Opened $app_name" else echo "Error: Could not open $app_name" fi ;;
"quit") if [[ -n "$pids" ]]; then if [[ -n "$bundle_id" ]]; then # Try graceful quit via bundle ID osascript -e "tell application \"$app_name\" to quit" 2>/dev/null || pkill "$app_name" else # Fallback to pkill pkill "$app_name" fi echo "Quit $app_name" else echo "$app_name is not running" fi ;;
"force_quit") if [[ -n "$pids" ]]; then pkill -9 -f "$app_name" echo "Force quit $app_name" else echo "$app_name is not running" fi ;;
"restart") if [[ -n "$pids" ]]; then # Quit first if [[ -n "$bundle_id" ]]; then osascript -e "tell application \"$app_name\" to quit" 2>/dev/null || pkill "$app_name" else pkill "$app_name" fi
# Wait a moment sleep 0.5
# Reopen open -a "$app_path" echo "Restarted $app_name" else echo "$app_name is not running - opening instead" open -a "$app_path" fi ;;
"finder") open -R "$app_path" echo "Showed $app_name in Finder" ;;
*) echo "Unknown action: $action" ;; esac
